function applyGeography(cities){geoRegistry=cities||{};if(Object.keys(geoRegistry).length)indexedCities=Object.keys(geoRegistry);for(const [city,meta] of Object.entries(geoRegistry))for(const alias of meta.aliases||[])cityAliases[alias]=city;document.querySelectorAll('datalist[id^=v16-cities-]').forEach(list=>{list.replaceChildren(...indexedCities.map(city=>{const op=el('option');op.value=city;return op;}));});}
