const BUNDLE_GROUPS={artists:'people',curators:'people',institution:'institutions',relatedInstitutions:'institutions',concepts:'concepts'};
const bundleNorm=s=>String(s||'').normalize('NFKC').toLowerCase().replace(/[\s\p{P}\p{S}]+/gu,'');
const bundleRows=type=>state.pendingNodes.filter(n=>n.type===type);
function bundleItems(type){return bundleRows(type).map(n=>({slug:n.slug,title:n.name,fields:{},pending:true}));}
function bundleLink(field,id){if(field==='institution')state.fields[field]=id;else state.fields[field]=[...new Set([...(state.fields[field]||[]),id])];}
function removeBundleNode(n){state.pendingNodes=state.pendingNodes.filter(x=>x!==n);for(const other of state.pendingNodes){for(const [field,target] of Object.entries({linkedInstitutions:'institutions',linkedPeople:'people',linkedExhibitions:'exhibitions',linkedConcepts:'concepts',linkedWriting:'writing'})){if(target===n.type&&(other[field]||[]).includes(n.slug)){other[field]=other[field].filter(id=>id!==n.slug);other.reviewed=false;}}}for(const [f,t] of Object.entries(BUNDLE_GROUPS)){if(t!==n.type)continue;if(f==='institution'){if(state.fields[f]===n.slug)state.fields[f]='';}else state.fields[f]=(state.fields[f]||[]).filter(x=>x!==n.slug);}for(const [key,target] of Object.entries({curators:'people',linkedPeople:'people',linkedInstitutions:'institutions',linkedExhibitions:'exhibitions',linkedConcepts:'concepts',linkedWriting:'writing'}))if(target===n.type&&Array.isArray(state.fields[key]))state.fields[key]=state.fields[key].filter(id=>id!==n.slug);setDirty();refreshLinkedUI();}
async function stageBundleNode(field,name,requestedId,body='',city=''){
 const type=BUNDLE_GROUPS[field];if(state.type!=='exhibitions'||!type)throw Error('Select an Exhibition first.');
 const title=String(name||'').trim();if(!title||title.length>300)throw Error('Enter a name (up to 300 characters).');
 const token=state.analysisNonce,record=state.fields;
 const items=await getList(type);let conceptMeta={};if(type==='concepts')conceptMeta=(await api('/api/concept-meta')).concepts||{};
 if(state.fields!==record||state.type!=='exhibitions')throw Error('Record changed; try again.');
 const match=items.find(x=>[x.title,x.slug,x.fields?.name,x.fields?.nativeName,...(x.fields?.alternativeNames||[]),x.fields?.sortName,x.fields?.reading,...(conceptMeta[x.slug]?.aliases||[])].some(v=>bundleNorm(v)&&bundleNorm(v)===bundleNorm(title)));
 if(match){const target=conceptMeta[match.slug]?.mergedInto||match.slug;bundleLink(field,target);setDirty();refreshLinkedUI();warn('Linked existing record: '+match.title+'. No duplicate created.');return;}
 const previous=bundleRows(type).find(n=>bundleNorm(n.name)===bundleNorm(title));if(previous){bundleLink(field,previous.slug);setDirty();refreshLinkedUI();warn('Linked staged record: '+previous.name);return;}
 let id=String(requestedId||'').trim()||slugify(title);
 if(!requestedId&&id==='new-record'){const bytes=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(title.normalize('NFKC').toLowerCase()));id=type+'-'+Array.from(new Uint8Array(bytes)).slice(0,8).map(b=>b.toString(16).padStart(2,'0')).join('');}
 if(state.fields!==record||state.type!=='exhibitions')throw Error('Record changed; try again.');
 if(!/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(id)||id.length>100)throw Error('Enter a valid unique English ID.');
 if([...items,...bundleItems(type)].some(x=>x.slug===id))throw Error('That record ID already exists. Use a different ID or link the existing entry.');
 if(state.pendingNodes.length>=200)throw Error('Limit: 200 new linked records in one exhibition.');
 state.pendingNodes.push({type,slug:id,name:title,body:String(body||''),kind:field==='curators'?'curator':'other',...(type==='institutions'?{city:canonicalCity(city)}:{}),reviewed:false});bundleLink(field,id);setDirty();refreshLinkedUI();warn('Added '+title+' to this Exhibition. Review it in the Publish section before publication.');
}
