 const draw=()=>{list.replaceChildren();const q=bundleNorm(search.value);const matches=active.filter(x=>!q||[x.title,x.slug,x.fields?.reading,x.fields?.sortName,x.fields?.nativeName,...(x.fields?.alternativeNames||[]),...aliasList(x)].some(v=>bundleNorm(v).includes(q)));const visible=type==='concepts'?matches:q?matches:matches.filter(x=>selected().has(x.slug));list.hidden=!visible.length&&!q;list.classList.toggle('concept-options',type==='concepts');for(const item of visible){const b=el('button','bundle-result',item.title+(item.pending?' · NEW':''));b.type='button';b.setAttribute('aria-pressed',String(selected().has(item.slug)));const mark=el('span','selection-mark',selected().has(item.slug)?'✓':'＋');b.prepend(mark);b.onclick=()=>choose(item.slug);list.append(b);}if(q&&!active.some(x=>bundleNorm(x.title)===q||aliasList(x).some(a=>bundleNorm(a)===q))){const create=el('button','action-link','+ Create “'+search.value.trim()+'”');create.type='button';create.onclick=()=>{addWrap.open=true;name.value=search.value.trim();name.focus();};list.append(create);}if(type==='concepts')catalogCount.textContent=`显示 ${matches.length} / ${active.length} 个有效概念 · 已合并的旧别名不会重复列出`;};
