async function saveDraft(){if(busy||sourcePending){warn('Please let the original snapshot finish first.');return;}busy=true;$('record-workspace').inert=true;document.querySelector('.sidebar').inert=true;try{const data=serialize();if(state.mode!=='draft'){const drafts=await api('/api/drafts?'+qs({type:state.type}));if(drafts.items.some(x=>x.slug===data.slug)&&!confirm('A separate private draft uses this ID. Replace that draft?'))return;}const result=await post('/api/draft',data);await finishRecovery();state.mode='draft';state.slug=data.slug;state.fields=data.fields;state.body=data.body;$('slug').disabled=true;$('record-mode').textContent='03 / PRIVATE DRAFT';setDirty(false);await loadList();warn('Private draft saved. Not published.');}catch(e){warn(e.message,true);}finally{busy=false;$('record-workspace').inert=false;document.querySelector('.sidebar').inert=false;if(state.dirty)scheduleRecovery();}}
