async function removeRecord(action){if(busy||sourcePending||state.mode!=='existing')return;if(state.dirty){warn('Publish or discard unsaved changes before removing the record.',true);return;}busy=true;try{const type=state.type,slug=state.slug;const preview=await api('/api/record-removal-preview?'+qs({type,slug}));if(preview.hash!==state.hash)throw Error('Record changed. Reload first.');const affected=preview.affected.map(x=>x.file+' ('+x.fields.join(', ')+')').join('\n');const message=(action==='withdraw'?'Withdraw / 撤回':'Delete local record / 删除档案')+'\n'+preview.title+'\n'+preview.affected.length+' affected files / 受影响文件\n'+affected+'\nHistorical snapshots, Git history, private originals and caches are not erased.\nType exact record ID: '+slug;if(prompt(message)!==slug)return;await post('/api/record-'+action,{type,slug,hash:preview.hash,confirm:slug});state.lists={};newRecord();await loadList();await refreshWithdrawn();warn('Local record removed. Build and Push to update the public site.');}catch(e){warn(e.message,true);}finally{busy=false;}}
