async function publish(){if(busy||sourcePending){warn('Please let the original snapshot finish first.');return;}busy=true;try{attemptedPublish=true;refreshV13();const issues=reviewIssues();if(issues.missing.length||issues.invalidId||issues.pending.length||issues.periodError){if(issues.invalidId)$('record-id-wrap').open=true;$('editor-review-status').dataset.status='error';throw Error('请先处理标红的必填项、会期、Record ID 或待审核关联。 / Resolve the highlighted items before publication.');}if(!$('confirm-public').checked)throw new Error('Please check the public-publication confirmation before publishing.');const data=serialize();const grouped=!!data.bundle?.length;if(grouped&&data.bundle.some(n=>!n.reviewed))throw new Error('Review all new linked records first, or remove those you do not want to publish.');data.confirmPublic=true;let result;$('record-workspace').inert=true;$('switch-research').disabled=true;$('switch-record').disabled=true;document.querySelector('.sidebar').inert=true;try{result=await post(grouped?'/api/bundle-publish':'/api/publish',data);}finally{$('record-workspace').inert=false;$('switch-research').disabled=false;$('switch-record').disabled=false;document.querySelector('.sidebar').inert=false;}await finishRecovery();if(grouped){for(const n of state.pendingNodes)state.lists[n.type]=null;state.pendingNodes=[];}state.mode='existing';state.slug=data.slug;state.fields=data.fields;state.hash=result.sha256;state.body=data.body;$('slug').disabled=true;$('record-mode').textContent='03 / EXISTING RECORD';$('confirm-public').checked=false;state.lists[state.type]=null;await loadList();renderFields();setDirty(false);window.dispatchEvent(new Event('editor-research-open'));warn('Local archive saved; research sync completed. Build and Push manually. Online status is not verified.');$('publication-progress').dataset.local='saved';}catch(e){warn(e.message,true);}finally{busy=false;if(state.dirty)scheduleRecovery();}}
