function analysisPayload(){return{type:'exhibitions',slug:$('slug').value.trim(),title:String(state.fields.title||''),location:String(state.fields.location||''),body:$('body').value,fields:{artists:state.fields.artists||[],concepts:state.fields.concepts||[],relatedInstitutions:state.fields.relatedInstitutions||[],institution:state.fields.institution||''}};}
function el(tag,className,text){const n=document.createElement(tag);if(className)n.className=className;if(text!==undefined)n.textContent=text;return n;}
async function runAnalysis(nonce){if(state.type!=='exhibitions'||!state.token)return;clearTimeout(state.analysisTimer);const call=nonce??++state.analysisNonce;const payload=analysisPayload();if(!payload.title.trim()&&!payload.body.trim()&&!payload.location.trim()){$('analysis-status').textContent='AWAITING TEXT';state.analysis=null;renderAnalysis();return;}
  $('analysis-status').textContent='SCANNING';try{const result=await post('/api/analyze',payload);if(call!==state.analysisNonce)return;state.analysis=result;state.aiSuggestions=null;state.reviewSelections=new Set();state.newSuggestions=result.newProposalReview?.newRecords||[];$('analysis-status').textContent='LOCAL / EVIDENCE-BASED';renderAnalysis();}catch(err){if(call!==state.analysisNonce)return;$('analysis-status').textContent='SCAN FAILED';const wrap=$('analysis-results');wrap.replaceChildren(el('p','analysis-placeholder',err.message));}}
function suggestionKey(g,item){return `${g}:${item.id}`;}
function suggestionGroups(){const local=state.analysis?.groups||{};const external=state.aiSuggestions?.groups||{};const output={people:[],institutions:[],concepts:[]};for(const group of Object.keys(output)){
  const seen=new Set();for(const item of [...(local[group]||[]),...(external[group]||[])]){if(seen.has(item.id))continue;seen.add(item.id);output[group].push(item);}
}return output;}
function renderAnalysis(){const pane=$('analysis-results');pane.replaceChildren();$('apply-analysis').disabled=true;if(state.type!=='exhibitions')return;
  if(!state.analysis){pane.append(el('p','analysis-placeholder','The local scan reads your exhibition title and notes. No link is written automatically.'));renderNewProposals();return;}
  pane.append(el('h3','analysis-summary-label','Preliminary reading'));
  pane.append(el('p','analysis-summary',state.analysis.summary));
  const keys=state.analysis.keywords||[];
  if(keys.length){const row=el('div','keyword-row');for(const k of keys){const span=el('span','keyword',k.term);row.append(span);}pane.append(row);}
  let total=0;const categories=[['people','People / Collectives'],['institutions','Institutions'],['concepts','Concepts']];const groups=suggestionGroups();
  for(const [key,label] of categories){const sec=el('div','analysis-group');const header=el('div','analysis-group-heading',`${label} · ${groups[key].length}`);sec.append(header);
    if(!groups[key].length)sec.append(el('p','analysis-none','No supported match yet.'));
    for(const item of groups[key]){total++;
      const row=el('label','analysis-candidate');const input=document.createElement('input');input.type='checkbox';input.checked=state.reviewSelections.has(suggestionKey(key,item));input.setAttribute('aria-label',`Approve ${item.title}`);
      input.onchange=()=>{const id=suggestionKey(key,item);if(input.checked)state.reviewSelections.add(id);else state.reviewSelections.delete(id);$('apply-analysis').disabled=state.reviewSelections.size===0;};
      const content=el('div','candidate-text'),first=el('div','candidate-title');first.append(el('strong','',item.title),el('span','candidate-method',item.method==='ai-inference'?'AI / REVIEW':item.method==='vocabulary'?'VOCABULARY MATCH':'EXACT MATCH'));content.append(first,el('p','candidate-reason',item.reason),el('blockquote','candidate-evidence',`“${item.evidence?.quote||''}”`),el('small','candidate-source',`Source: ${item.evidence?.source||'note'} · Existing ID: ${item.id}`));row.append(input,content);sec.append(row);
    }pane.append(sec);
  }
  if(total===0)pane.append(el('p','analysis-placeholder','No existing IDs matched. You can still edit relations manually or request AI-assisted ideas.'));
  if(state.aiSuggestions)pane.append(el('p','analysis-note',`${state.aiSuggestions.acceptedCandidates} AI candidates passed ID and quote checks; ${state.aiSuggestions.discarded} were rejected. All are still unverified suggestions.`));
  const similar=state.analysis.similar||[];if(similar.length){const sec=el('div','analysis-group');sec.append(el('div','analysis-group-heading','Related archived exhibitions / overlap only'));for(const item of similar.slice(0,6)){const row=el('div','similar-item');row.append(el('strong','',item.title),el('small','',`Shared record IDs: ${item.shared.join(', ')}. This does not establish a meaningful relationship.`));sec.append(row);}pane.append(sec);}
  $('apply-analysis').disabled=state.reviewSelections.size===0;
  renderNewProposals();
}
async function applyAnalysis(){const groups=suggestionGroups();let count=0;for(const [g,items] of Object.entries(groups))for(const item of items){if(!state.reviewSelections.has(suggestionKey(g,item)))continue;
  if(g==='people'){const list=new Set(state.fields.artists||[]);if(!list.has(item.id)){list.add(item.id);state.fields.artists=[...list];count++;}}
  if(g==='concepts'){const list=new Set(state.fields.concepts||[]);if(!list.has(item.id)){list.add(item.id);state.fields.concepts=[...list];count++;}}
  if(g==='institutions'){if(!state.fields.institution&&item.evidence?.source==='location'){state.fields.institution=item.id;count++;}
    else if(state.fields.institution!==item.id){const list=new Set(state.fields.relatedInstitutions||[]);if(!list.has(item.id)){list.add(item.id);state.fields.relatedInstitutions=[...list];count++;}}}
}if(count){setDirty();refreshLinkedUI();warn(`${count} reviewed relation(s) added to form. Nothing has been published. Save a private draft or publish later.`);}else warn('No new references were added; they may already be in the record.');}
async function copyAiPrompt(){try{const result=await post('/api/ai-prompt',analysisPayload());try{await navigator.clipboard.writeText(result.prompt);warn('AI prompt copied. Paste it into ChatGPT, then paste the JSON response below. The prompt includes your note content.');}catch{const t=$('ai-json');t.value=result.prompt;t.select();warn('Clipboard blocked. Prompt placed in the text area; copy it manually, then replace it with AI JSON.');}}catch(e){warn(e.message,true)}}
async function importAi(){try{const value=$('ai-json').value.trim();if(!value)throw new Error('Paste AI JSON first.');const result=await post('/api/ai-review',{...analysisPayload(),ai:value});state.aiSuggestions=result;state.reviewSelections=new Set();mergeNewSuggestions(result.newRecords||[]);renderAnalysis();warn(`Validated ${result.acceptedCandidates} existing links and ${result.newAccepted||0} new record proposals; ${result.newDiscarded||0} new proposals rejected. Review each before saving.`);}catch(e){warn(e.message,true)}}
function mergeNewSuggestions(items){
  const existing=new Set(state.newSuggestions.map(x=>x.group+':'+x.name.normalize('NFKC').toLowerCase()));
  for(const item of items){const key=item.group+':'+item.name.normalize('NFKC').toLowerCase();if(existing.has(key))continue;existing.add(key);state.newSuggestions.push(item);}
}
function sourceForNew(){const p=analysisPayload();return{slug:p.slug,title:p.title,location:p.location,body:p.body};}
function renderNewProposals(){
  const pane=$('new-node-list');pane.replaceChildren();
  if(state.type!=='exhibitions')return;
  if(!state.newSuggestions.length){pane.append(el('p','analysis-none','No new records proposed. Add an explicit line (Director: … / Institution: … / Concept: …), use manual proposal, or import AI JSON.'));return;}
  for(const item of state.newSuggestions){
    const row=el('div','new-node-candidate');
    const title=el('div','candidate-title');title.append(el('strong','',item.name),el('span','candidate-method',`${item.group.toUpperCase()} · ${item.method==='explicit-label'?'EXPLICIT LABEL':'AI / INFERENCE'}`));row.append(title);
    row.append(el('p','candidate-reason',item.reason));
    row.append(el('blockquote','candidate-evidence',`“${item.evidence?.quote||''}”`));
    if(item.possibleDuplicates?.length)row.append(el('p','analysis-note','Possible existing records: '+item.possibleDuplicates.map(x=>`${x.title} (${x.id})`).join(', ')+'. Check these before creating a new node.'));
    const slugWrap=el('label','new-slug-label','Proposed ID (lowercase)');const slugInput=el('input','new-slug-input');slugInput.type='text';slugInput.value=item.id;slugInput.setAttribute('aria-label','New record ID for '+item.name);slugWrap.append(slugInput);row.append(slugWrap);
    const actions=el('div','new-node-actions');const create=el('button','action-link','Add to this Exhibition');create.type='button';
    const notice=el('span','analysis-note');const key=item.group+':'+item.id;
    if(state.createdNewDrafts.has(key)){create.disabled=true;notice.textContent='Added here · review in Publish';}
    create.onclick=async()=>{
      create.disabled=true;notice.textContent='Checking duplicate records…';
      try{
        const candidate={group:item.group,name:item.name,id:slugInput.value.trim(),evidence:item.evidence.quote,reason:item.reason,method:item.method};
        const result=await post('/api/new-review',{source:sourceForNew(),candidate});
        const checked=result.candidate;const field=checked.group==='people'?'artists':checked.group==='concepts'?'concepts':(!state.fields.institution&&checked.evidence?.source==='location'?'institution':'relatedInstitutions');
        await stageBundleNode(field,checked.name,slugInput.value.trim());
        state.createdNewDrafts.add(item.group+':'+slugInput.value.trim());
        notice.textContent='Added to this Exhibition. Review in Publish before publishing.';
      }catch(e){notice.textContent=e.message;create.disabled=false;}
    };actions.append(create,notice);row.append(actions);pane.append(row);
  }
}
async function addManualProposal(){
  try{
    const candidate={group:$('manual-group').value,name:$('manual-name').value.trim(),evidence:$('manual-evidence').value.trim(),reason:$('manual-reason').value.trim()};
    const r=await post('/api/new-review',{source:sourceForNew(),candidate});
    mergeNewSuggestions([r.candidate]);renderNewProposals();warn('New proposal added for review. No draft or public record has been created.');
  }catch(e){warn('Cannot add candidate: '+e.message,true);}
}
$('check-manual-new').addEventListener('click',addManualProposal);
$('run-analysis').addEventListener('click',()=>{state.analysisNonce++;runAnalysis(state.analysisNonce);});$('apply-analysis').addEventListener('click',applyAnalysis);$('copy-ai-prompt').addEventListener('click',copyAiPrompt);$('import-ai').addEventListener('click',importAi);
async function boot(){try{const data=await api('/api/bootstrap');state.token=data.token;state.writingRoute=!!data.writingRoute;try{const geo=await api('/api/geography');applyGeography(geo.cities);}catch{}renderCollectionTabs();newRecord();workspaceUI('capture');await loadList();await loadRecoveries();}catch(e){warn('Cannot connect to the local editor server: '+e.message,true);}}
$('new-record').addEventListener('click',()=>{if(!ensureSafeSwitch())return;newRecord();});$('filter-records').addEventListener('input',renderList);$('body').addEventListener('input',()=>setDirty());$('slug').addEventListener('input',()=>{$('slug').dataset.manual='true';state.slug=$('slug').value.trim();setDirty();});$('save-draft').addEventListener('click',saveDraft);$('delete-draft').addEventListener('click',deleteDraft);$('edit-form').addEventListener('submit',e=>{e.preventDefault();publish();});$('toggle-preview').addEventListener('click',preview);$('body-outline').addEventListener('click',outline);
for(const [id,view] of [['show-published','published'],['show-drafts','drafts']])$(id).addEventListener('click',async()=>{state.view=view;$('show-published').classList.toggle('selected',view==='published');$('show-drafts').classList.toggle('selected',view==='drafts');await loadList();});
for(const b of document.querySelectorAll('[data-editor-jump]'))b.addEventListener('click',()=>$(b.dataset.editorJump)?.scrollIntoView({behavior:'smooth',block:'start'}));
$('link-current-question').addEventListener('click',()=>{if(state.mode!=='existing'||state.dirty||!state.slug||busy)return;const record=state.type+':'+state.slug;showResearch(true);window.dispatchEvent(new CustomEvent('editor-link-question',{detail:{record}}));});
$('switch-record').addEventListener('click',()=>showResearch(false));$('switch-research').addEventListener('click',()=>showResearch(true));
$('editor-toast-close').addEventListener('click',()=>{$('editor-toast').hidden=true;clearTimeout(v15ToastTimer);});
$('workspace-capture').onclick=async()=>{if(busy||sourcePending)return;if(state.type!=='exhibitions'){if(!ensureSafeSwitch())return;state.type='exhibitions';state.view='published';newRecord();await loadList();}showResearch(false);workspaceUI('capture');};
$('workspace-archive').onclick=()=>{if(busy||sourcePending)return;showResearch(false);workspaceUI('archive');renderList();};
$('workspace-research').onclick=()=>{if(!busy&&!sourcePending)showResearch(true);};
$('archive-maintenance').onchange=renderList;
window.addEventListener('editor-original-saved',()=>setDirty());
$('body').addEventListener('paste',async event=>{
 if(sourcePending||state.mode!=='new'||$('body').value.trim()||window.__murmurgroveOriginalSha)return;
 const text=event.clipboardData?.getData('text/plain');if(!text?.trim())return;
 const id=recoveryId;try{sourcePending=post('/api/capture-original',{text,title:$('editor-title').textContent.slice(0,150)});const result=await sourcePending;if(id===recoveryId){window.__murmurgroveOriginalSha=result.sha256;$('original-message').textContent='First paste preserved privately.';setDirty();}}catch(e){if(id===recoveryId)warn('Original snapshot failed: '+e.message,true);}finally{sourcePending=null;}
});
boot();

$('profile-extract').addEventListener('click',async()=>{const record=state.fields;try{const fields=Object.fromEntries(Object.entries(record).filter(([k,v])=>v!==''&&v!=null&&(!Array.isArray(v)||v.length)));const {suggestions}=await post('/api/profile-suggestions',{type:state.type,fields,body:$('body').value});if(record!==state.fields)return;const pairs=Object.entries(suggestions||{});if(!pairs.length){warn('No unfilled explicitly labelled details found / 未发现可提取的明确资料。');return;}if(!confirm('Apply these explicitly labelled details? / 应用以下资料？\n'+pairs.map(([k,v])=>k+': '+(Array.isArray(v)?v.join(' · '):v)).join('\n')))return;Object.assign(record,suggestions);renderFields();$('advanced-fields-wrap').open=true;setDirty();warn('Details added to the form; review before publishing.');}catch(e){warn(e.message,true);}});
